/** Strict immutable native before images. Unknown palettes and lossy tile factories never become AIR. */
final class NativeGearSnapshot {
    static final int MAX_BYTES=2*1024*1024;
    static final class Cell {
        final BlockPos pos;final BlockState state;final boolean section;private final CompoundTag raw;
        Cell(BlockPos pos,BlockState state,CompoundTag raw){this(pos,state,raw,false);}
        Cell(BlockPos pos,BlockState state,CompoundTag raw,boolean section){this.section=section;this.pos=pos.immutable();this.state=Objects.requireNonNull(state);this.raw=raw==null?null:raw.copy();if(state.hasBlockEntity()!=(raw!=null))throw new IllegalArgumentException("Arm snapshot tile/state mismatch");if(raw!=null&&raw.sizeInBytes()>MAX_BYTES)throw new IllegalArgumentException("Arm tile snapshot byte bound");}
        CompoundTag tile(){return raw==null?null:raw.copy();}
        int bytes(){return 128+(raw==null?0:raw.sizeInBytes());}
        Cell at(BlockPos next,BlockState rotated){var tag=tile();if(tag!=null){tag.putInt("x",next.getX());tag.putInt("y",next.getY());tag.putInt("z",next.getZ());}return new Cell(next,rotated,tag,section);}
        CompoundTag write(){var tag=new CompoundTag();tag.putInt("X",pos.getX());tag.putInt("Y",pos.getY());tag.putInt("Z",pos.getZ());tag.put("State",NbtUtils.writeBlockState(state));if(raw!=null)tag.put("Tile",raw.copy());if(section)tag.putBoolean("ArmSection",true);return tag;}
    }
    static boolean loaded(ServerLevel level,BlockPos pos){return NativeGearFormation.loaded(level,pos);}
    static BlockState decode(HolderLookup.Provider registries,CompoundTag tag){if(!tag.contains("Name",Tag.TAG_STRING))throw new IllegalArgumentException("Missing arm palette identity");tag=com.vandorlabs.neoforge.navigation.observer.NativeObserverAliases.palette(tag);var id=ResourceLocation.tryParse(tag.getString("Name"));if(id==null||!BuiltInRegistries.BLOCK.containsKey(id))throw new IllegalArgumentException("Unknown arm palette block");var expanded=tag.copy();var block=BuiltInRegistries.BLOCK.get(id);if(block instanceof NativeGearBlock){if(expanded.contains("Properties")&&!expanded.contains("Properties",Tag.TAG_COMPOUND))throw new IllegalArgumentException("Malformed arm palette properties");var properties=expanded.getCompound("Properties");if(!properties.contains("part"))properties.putString("part","0");if(!properties.contains("assembled"))properties.putString("assembled","false");expanded.put("Properties",properties);}var state=NbtUtils.readBlockState(registries.lookupOrThrow(Registries.BLOCK),expanded);if(!NbtUtils.writeBlockState(state).equals(expanded))throw new IllegalArgumentException("Unknown arm palette properties");return state;}
    static Cell read(HolderLookup.Provider registries,CompoundTag tag,BlockPos root){if(!tag.getAllKeys().stream().allMatch(Set.of("X","Y","Z","State","Tile","ArmSection")::contains))throw new IllegalArgumentException("Unknown arm cell field");for(String axis:List.of("X","Y","Z"))if(!tag.contains(axis,Tag.TAG_INT))throw new IllegalArgumentException("Malformed arm cell coordinate");if(!tag.contains("State",Tag.TAG_COMPOUND)||tag.contains("Tile")&&!tag.contains("Tile",Tag.TAG_COMPOUND))throw new IllegalArgumentException("Malformed arm cell snapshot");var pos=new BlockPos(tag.getInt("X"),tag.getInt("Y"),tag.getInt("Z"));if(Math.abs((long)pos.getX()-root.getX())>64||Math.abs((long)pos.getY()-root.getY())>64||Math.abs((long)pos.getZ()-root.getZ())>64)throw new IllegalArgumentException("Arm cell footprint bound");if(tag.contains("ArmSection")&&(!tag.contains("ArmSection",Tag.TAG_BYTE)||!tag.getBoolean("ArmSection")))throw new IllegalArgumentException("Malformed arm section role");return new Cell(pos,decode(registries,tag.getCompound("State")),tag.contains("Tile")?tag.getCompound("Tile"):null,tag.getBoolean("ArmSection"));}
    static Cell capture(ServerLevel level,BlockPos pos,boolean root){if(!loaded(level,pos))throw new IllegalArgumentException("Load the complete arm attachment first");var state=level.getBlockState(pos);var tile=level.getBlockEntity(pos);if(state.hasBlockEntity()&&tile==null)throw new IllegalArgumentException("Arm source tile is still loading");if(tile instanceof RandomizableContainerBlockEntity loot&&loot.getLootTable()!=null)throw new IllegalArgumentException("Open the loot container before moving it");if(state.getBlock() instanceof ChestBlock&&state.getValue(BlockStateProperties.CHEST_TYPE)!=ChestType.SINGLE)throw new IllegalArgumentException("Separate linked chests before moving them");if(!root)requireNoExternalNetwork(level,pos,state,tile);var cell=new Cell(pos,state,tile==null?null:tile.saveWithFullMetadata(level.registryAccess()));stage(level,cell,root);return cell;}
    private static void requireNoExternalNetwork(ServerLevel level,BlockPos pos,BlockState state,BlockEntity tile){
        var caps=net.neoforged.neoforge.capabilities.Capabilities.EnergyStorage.BLOCK;
        boolean builder=NativeGearBuilderCapture.builder(state);
        for(var side:new Direction[]{null,Direction.DOWN,Direction.UP,Direction.NORTH,Direction.SOUTH,Direction.WEST,Direction.EAST}){
            var fluid=level.getCapability(net.neoforged.neoforge.capabilities.Capabilities.FluidHandler.BLOCK,pos,side);
            var energy=level.getCapability(caps,pos,side);
            var items=builder||building(tile)||tile instanceof NativeResourcePortEntity?level.getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,pos,side):null;
            boolean nativeFluid=tile instanceof NativeFluidPortEntity port&&fluid==port.fluid(side);
            boolean nativePower=tile instanceof NativePowerPortEntity port&&energy==port.energy(side);
            boolean nativeItems=tile instanceof NativeMatterPortEntity port&&items==port.items(side);
            if(fluid!=null&&!nativeFluid||external(energy,builder)&&!nativePower||external(items,builder)&&!nativeItems)
                throw new IllegalArgumentException("External arm attachment network retained");
        }
    }
    private static boolean external(Object capability,boolean builder){
        return capability!=null&&(!builder||!com.vandorlabs.neoforge.builders.NativeBuilderBindings.nativePort(capability));
    }
    private static boolean building(BlockEntity tile){if(!(tile instanceof com.vandorlabs.neoforge.ProgrammableBlockEntity))return false;var block=tile.getBlockState().getBlock();return block==com.vandorlabs.neoforge.VandorLabsBootstrap.PROGRAMMABLE_BLOCK.get()||block==com.vandorlabs.neoforge.VandorLabsBootstrap.PROGRAMMABLE_SLAB.get()||block==com.vandorlabs.neoforge.VandorLabsBootstrap.PROGRAMMABLE_STAIRS.get();}
    private static boolean supported(BlockEntity tile,boolean root){return root?tile instanceof NativeGearEntity gear&&!gear.inert():building(tile)||tile instanceof com.vandorlabs.neoforge.builders.NativeBuilderEntity builder&&!builder.inert()||tile instanceof com.vandorlabs.neoforge.builders.NativeBuilderPartEntity part&&!part.inert()||tile instanceof com.vandorlabs.neoforge.appliances.NativeApplianceEntity appliance&&!appliance.inert()||tile instanceof com.vandorlabs.neoforge.navigation.observer.NativeObserverEntity observer&&!observer.inert()||tile instanceof com.vandorlabs.neoforge.navigation.observer.NativeObserverPartEntity part&&!part.inert()||tile instanceof com.vandorlabs.neoforge.navigation.NativeNavigationTableEntity table&&!table.inert()||tile instanceof NativeResourcePortEntity port&&!port.inert()||tile instanceof ChestBlockEntity||tile instanceof BarrelBlockEntity||tile instanceof SignBlockEntity||tile instanceof com.vandorlabs.neoforge.storage.NativeStorageEntity storage&&!storage.inert()||tile instanceof com.vandorlabs.neoforge.rack.NativeRackEntity rack&&!rack.inert();}
    static BlockEntity stage(ServerLevel level,Cell cell,boolean root){return stage(level.registryAccess(),cell,root);}
    static BlockEntity stage(HolderLookup.Provider registries,Cell cell,boolean root){if(cell.raw==null)return null;if(!(cell.state.getBlock() instanceof EntityBlock factory))throw new IllegalArgumentException("Missing arm tile factory");var tile=factory.newBlockEntity(cell.pos,cell.state);if(tile==null||!supported(tile,root||cell.section)&&!(tile instanceof com.vandorlabs.neoforge.navigation.observer.NativeObserverPartEntity&&!root&&!cell.section)&&!(tile instanceof com.vandorlabs.neoforge.builders.NativeBuilderPartEntity&&!root&&!cell.section))throw new IllegalArgumentException("Unsupported arm attachment tile");var raw=cell.tile();if(tile instanceof com.vandorlabs.neoforge.builders.NativeBuilderEntity)com.vandorlabs.neoforge.builders.NativeBuilderTransfer.requireIdleData(raw);if(raw.contains("ForgeCaps")&&(!raw.contains("ForgeCaps",Tag.TAG_COMPOUND)||!raw.getCompound("ForgeCaps").isEmpty())||raw.contains("ForgeData")&&!raw.contains("ForgeData",Tag.TAG_COMPOUND)||raw.contains("neoforge:attachments")&&(!raw.contains("neoforge:attachments",Tag.TAG_COMPOUND)||!raw.getCompound("neoforge:attachments").isEmpty()))throw new IllegalArgumentException("Unsupported external arm attachment ownership");if(building(tile)){if(!com.vandorlabs.neoforge.screen.NativeScreenOwnership.installable(raw))throw new IllegalArgumentException("Owned building reader/surface retained");var transmission=com.vandorlabs.neoforge.redstone.NativeTransmissionMigration.read(raw);if(!transmission.installable()||!transmission.install().equals(raw))throw new IllegalArgumentException("Owned building module retained");}NativePlatformComponents.requireSupported(raw,registries);try(var guard=NativePlatformComponents.guardLoad(tile)){tile.loadWithComponents(raw,registries);guard.requireSuccessful();}var expected=cell.tile();if(root&&tile instanceof NativeGearEntity gear&&expected.getCompound("NativeGearPayload").getInt("Schema")==1&&gear.payload()!=null)expected.put("NativeGearPayload",gear.payload().write());if(!supported(tile,root||cell.section)||!same(expected,tile.saveWithFullMetadata(registries)))throw new IllegalArgumentException("Lossy arm attachment tile roundtrip");return tile;}
    static boolean same(CompoundTag a,CompoundTag b){if(Objects.equals(a,b))return true;if(a==null||b==null)return false;var x=com.vandorlabs.neoforge.navigation.observer.NativeObserverAliases.tile(a).copy();var y=com.vandorlabs.neoforge.navigation.observer.NativeObserverAliases.tile(b).copy();for(var tag:List.of(x,y)){com.vandorlabs.surface.TextureJoinSettings.normalizeLegacy(new com.vandorlabs.neoforge.ModernHousingTags(tag));if(tag.contains("keepPacked",Tag.TAG_BYTE)&&!tag.getBoolean("keepPacked"))tag.remove("keepPacked");if(tag.contains("NeoForgeData",Tag.TAG_COMPOUND)&&tag.getCompound("NeoForgeData").isEmpty())tag.remove("NeoForgeData");}return x.equals(y);}
    static boolean matches(ServerLevel level,Cell cell){if(!loaded(level,cell.pos)||level.getBlockState(cell.pos)!=cell.state)return false;var tile=level.getBlockEntity(cell.pos);return cell.raw==null?tile==null:tile!=null&&same(cell.raw,tile.saveWithFullMetadata(level.registryAccess()));}
    static void install(ServerLevel level,Cell cell,BlockEntity staged){var current=level.getBlockEntity(cell.pos);if(current instanceof com.vandorlabs.neoforge.rack.NativeRackEntity rack)rack.clearForTransfer();if(current instanceof Container inventory)inventory.clearContent();if(level.getBlockState(cell.pos)!=cell.state)try(var write=NativeGearHolds.writeOnce(level,cell.pos)){if(!level.setBlock(cell.pos,cell.state,Block.UPDATE_KNOWN_SHAPE))throw new IllegalStateException("Arm block publication refused");}if(cell.raw!=null){if(staged==null)throw new IllegalStateException("Prepared arm tile missing");level.removeBlockEntity(cell.pos);level.setBlockEntity(staged);staged.setChanged();}else if(level.getBlockEntity(cell.pos)!=null)level.removeBlockEntity(cell.pos);level.getChunkAt(cell.pos).setUnsaved(true);if(!matches(level,cell))throw new IllegalStateException("Arm publication did not preserve its snapshot");}
    private NativeGearSnapshot(){}
}
